INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 49, 'theory', 'Quiz: performance');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 49, 0, 'What should you do before optimizing?', '["Measure and find the bottleneck with a profiler", "Rewrite the code in C", "Remove all the functions", "Turn on debug mode"]', 0, 'Optimizing by guesswork wastes time on the unimportant and hurts readability.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 49, 1, 'What does the minimum over several timeit.repeat series give you?', '["The average of all runs", "The time of the slowest run", "An estimate with the least noise from other processes", "Nothing"]', 2, 'Noise only increases the time, so the minimum is closest to the true cost of the code.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 49, 2, 'What does the tottime column in cProfile show?', '["Time together with nested calls", "The time of the function itself, without nested calls", "The number of calls", "The program startup time"]', 1, 'cumtime is the time together with the functions it called, and ncalls is the number of calls.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 49, 3, 'Why does @functools.cache make a recursive fib fast?', '["It compiles the function to machine code", "It runs the calls in parallel", "It turns off recursion", "It remembers results, so each value is computed once"]', 3, 'Without a cache the number of calls grows exponentially, with a cache it grows linearly.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 49, 4, 'What does Amdahl''s law say?', '["Parallel code always speeds up by as many times as there are cores", "The speedup is limited by the share of work that cannot be parallelized", "Threads are faster than processes", "A cache always helps"]', 1, 'If 10% of the work is sequential, you cannot speed it up by more than 10 times.');
